package com.nextgen.gameaggregator.vendor.cosmoplay.api.balance;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.constraints.NotBlank;
import lombok.Builder;
import lombok.Data;
import lombok.extern.jackson.Jacksonized;

@Data
@Builder
@Jacksonized
@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
public class BalanceRequest {

    // The authentication token generated by our systema for partners.
    // It is included in the H5 game launch URL's "atk" parameter.
    @NotBlank
    @JsonProperty("AuthToken")
    private String authToken;

    // The unique identifier for the player on the partner server. The same
    // we include in included in the H5 game launch URL's "pid" parameter
    @NotBlank
    @JsonProperty("PlayerID")
    private String playerID;

    //The name of the game being launched, as specified in the H5
    // game launch URL's "gid" parameter.
    @NotBlank
    @JsonProperty("GameID")
    private String gameID;
}
